using System;using System.Net;using System.Net.Http;using System.Text;using System.Text.Json;using System.Text.RegularExpressions;using System.Threading;using System.Threading.Tasks;namespace CriterionArt.Provider;internal static class CriterionLivewireClient{    public static async Task<string?> GetSearchResponseJsonAsync(        HttpClient client, CookieContainer cookies, string query, CancellationToken ct)    {        // Step 1: solve Cloudflare via FlareSolverr, get real homepage HTML + clearance cookies        var solved = await FlareSolverrClient.SolveAsync(client, "https://www.criterion.com/", ct);        if (solved is null) return null;        foreach (Cookie c in solved.Cookies)            cookies.Add(new Uri("https://www.criterion.com"), c);        var homeHtml = solved.Html;        var tokenMatch = Regex.Match(homeHtml, "name=\"csrf-token\" content=\"([^\"]+)\"");        var snapshotMatch = Regex.Match(homeHtml, "wire:snapshot=\"(.*?)\"\\s", RegexOptions.Singleline);        if (!tokenMatch.Success || !snapshotMatch.Success) return null;        var token = tokenMatch.Groups[1].Value;        var snapshotJson = WebUtility.HtmlDecode(snapshotMatch.Groups[1].Value);        // Step 2: POST the search update — clearance cookie now rides along via the shared CookieContainer        var payload = new        {            _token = token,            components = new[]            {                new                {                    snapshot = snapshotJson,                    updates = new { search = query },                    calls = Array.Empty<object>()                }            }        };        var body = JsonSerializer.Serialize(payload);        using var request = new HttpRequestMessage(HttpMethod.Post, "https://www.criterion.com/livewire/update")        {            Content = new StringContent(body, Encoding.UTF8, "application/json")        };        request.Headers.Add("X-Livewire", "true");        request.Headers.Referrer = new Uri("https://www.criterion.com/");        var response = await client.SendAsync(request, ct);        if (!response.IsSuccessStatusCode) return null;        return await response.Content.ReadAsStringAsync(ct);    }}